rule.example:

class Account {
    private decimal _balance;
    public decimal WithInterest(decimal rate) {
        return _balance * (1 + rate);  // implicit input: member _balance
    }
}


class Account {
    private decimal _balance;
    private readonly List<decimal> _history = new();
    public void Deposit(decimal amount) {
        _balance += amount;     // implicit output: member _balance
        _history.Add(amount);   // implicit output: member _history
    }
}
